

// Factory helper for concise case study definitions
function cs(
  slug: string,
  title: string,
  client: string,
  category: string,
  challenge: string,
  solution: string,
  result: string,
  testimonial?: { quote: string; author: string; role?: string; company?: string }
): CaseStudy {
  return {
    slug,
    title,
    client,
    category,
    meta: { title: `${title} | ITD Case Study`, description: `${title}. ${challenge.slice(0, 120)}` },
    hero: { heading: title, subheading: `A case study with ${client}` },
    challenge,
    solution,
    result,
    sections: [],
    ...(testimonial ? { testimonial } : {}),
  };
}

